   959  static void skip_bits(struct rar5* rar, int bits) {
   960      const int new_bits = rar->bits.bit_addr + bits;
   961      rar->bits.in_addr += new_bits >> 3;
   962      rar->bits.bit_addr = new_bits & 7;
   963  }
