  1137  static uint64_t time_win_to_unix(uint64_t win_time) {
  1138      const size_t ns_in_sec = 10000000;
  1139      const uint64_t sec_to_unix = 11644473600LL;
  1140      return win_time / ns_in_sec - sec_to_unix;
